#ifndef SIRKIT_ANGLE_LESS_DEFINED
#define SIRKIT_ANGLE_LESS_DEFINED
struct AngleLess {
    constexpr bool operator()(const std::pair<std::int64_t, std::int64_t>& a,
                              const std::pair<std::int64_t, std::int64_t>& b) const noexcept {
