     z=[x for x in rows if x['compiler']==compiler and x['cfg']==cfg and x['mode']==mode and x['n']==n and x['shape']==shape and x['descending']==desc];d={v:statistics.median(x['ms']for x in z if x['variant']==v)for v in ['base','adaptive','adaptive2','control']};s.append(dict(compiler=compiler,cfg=cfg,mode=mode,n=n,shape=shape,descending=desc,ms=d,ratio={v:d[v]/d['base']for v in d}))
